R=pathlib.Path(__file__).resolve().parent;D=R/'reviews'/('round-'+(sys.argv[1] if len(sys.argv)>1 else '018'));S=D/'input'
now=lambda:datetime.datetime.now(datetime.timezone.utc).isoformat();sha=lambda b:hashlib.sha256(b).hexdigest()
if D.exists():raise SystemExit('018 exists; inspect before retry')
for p in (R/'reviews').glob('round-*/process.json'):
 if json.loads(p.read_text()).get('status')=='running' and not (p.parent/'completion.json').exists():raise SystemExit('Potential active review '+str(p))
D.mkdir();S.mkdir()
paths=[R/'design-c4/docs/Android MCP Bridge Design.md']
paths+=sorted((R/'design-c4/architecture').glob('*'))
paths+=sorted((R/'design-c4/docs/diagrams').glob('*.svg'))+sorted((R/'design-c4/docs/screens').glob('*.svg'))
